'use strict';const M=Model,U=OmniUI,$=id=>document.getElementById(id);let state=M.empty(),selected=null,start=false,locked=false,loadEpoch=0,recoveryFocus=null;window.OMNI_PREVIEW=!window.omnibloomHost;function show(){const filter=$('filter').value,items=start?M.projection(state):state.items.filter(x=>filter==='all'||filter==='done'&&x.done||filter===x.kind&&!x.done);$('list').replaceChildren();for(const x of items){const c=document.createElement('article');c.className='tile';const h=document.createElement('h2');h.textContent=x.title;const p=document.createElement('p');p.textContent=(x.kind==='video'?'Watch later':'Reading')+' · '+new URL(x.url).hostname+(x.done?' · Completed':'');const row=document.createElement('div');row.className='row';const open=document.createElement('button');open.textContent='Open';open.onclick=async()=>{try{const r=await U.request('navigation.open',{url:x.url},()=>({accepted:true}));if(r?.accepted!==true)throw Error();U.notify(window.OMNI_PREVIEW?'Preview: selected '+x.title:'Opening saved link.')}catch(_){U.notify('Could not open this link.')}};const more=document.createElement('button');more.textContent='More';more.onclick=()=>{selected=x.id;$('more-title').textContent=x.title;$('done').textContent=x.done?'Mark unread':'Mark completed';U.modal('more')};row.append(open,more);c.append(h,p,row);$('list').append(c)}if(!items.length){const p=document.createElement('p');p.className='empty';p.textContent=start?'Nothing waiting on your start page.':'No saved links in this view.';$('list').append(p)}$('start').textContent=start?'Full reading list':'Start page preview'}async function update(op){if(locked)throw Error('Reload to recover the saved list.');const next=M.change(state,op);if(window.omnibloomHost){const r=await U.request('readingList.commit',{expectedRevision:state.revision,state:next});state=M.validate(r)}else state=M.commit(localStorage,state,next);show();window.dispatchEvent(new CustomEvent('omni-reading-list-changed',{detail:{revision:state.revision}}))}function syncRecovery(){const add=$('add'),lost=document.activeElement===add;add.disabled=locked;if(locked&&lost){const target=$('filter');if(!target.disabled&&!target.closest('[hidden],[inert]')){U.focus(target);recoveryFocus=target}}else if(!locked&&recoveryFocus){if(document.activeElement===recoveryFocus&&!add.closest('[hidden],[inert]'))U.focus(add);recoveryFocus=null;}}
async function load(){const token=++loadEpoch;try{const next=window.omnibloomHost?M.validate(await U.request('readingList.read',{})):M.load(localStorage);if(token!==loadEpoch)return;state=next;locked=false;show();syncRecovery();U.notify(window.OMNI_PREVIEW?'Local preview · shared with this origin’s start page.':'Saved on this console.')}catch(_){if(token!==loadEpoch)return;locked=true;syncRecovery();U.notify('Saved list is unavailable. Existing data has not been overwritten.')}}$('add').onclick=()=>{if(locked)return;$('title').value='';$('url').value='';$('error').textContent='';U.modal('editor')};$('save').onclick=async()=>{if($('save').disabled)return;$('save').disabled=true;try{await update({type:'add',id:Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join(''),title:$('title').value,url:$('url').value,kind:$('kind').value,private:false});U.close();U.notify('Saved for later.')}catch(e){$('error').textContent=e.message}finally{$('save').disabled=false}};$('done').onclick=async()=>{try{await update({type:'toggle',id:selected});U.close()}catch(e){U.notify(e.message)}};$('remove').onclick=async()=>{try{await update({type:'remove',id:selected});U.close()}catch(e){U.notify(e.message)}};$('filter').onchange=()=>{start=false;show()};$('start').onclick=()=>{start=!start;show()};window.addEventListener('storage',e=>{if(e.key===M.KEY)load()});window.addEventListener('omni-reading-list-updated',load);load();U.focus($('add'));
